mapper.select:
SELECT

FROM attribute a WHERE 1 = 1

    AND a.user_id LIKE CONCAT('%',#{userId}, '%')


    AND a.account LIKE CONCAT('%',#{account}, '%')
    /** AND a.account = #{account} */


    AND a.phone_number LIKE CONCAT('%',#{phoneNumber}, '%')
    /** AND a.phone_number = #{phoneNumber} */


    AND a.area_code LIKE CONCAT('%',#{areaCode}, '%')
    /** AND a.area_code = #{areaCode} */


    AND a.email LIKE CONCAT('%',#{email}, '%')
    /** AND a.email = #{email} */


    AND a.nickname LIKE CONCAT('%',#{nickname}, '%')


    AND a.gender = #{gender}


    AND a.create_time = #{createTime}


    AND a.change_time = #{changeTime}


    AND a.level = #{level}


    AND a.allow_vibration = #{allowVibration}


    AND a.allow_beep = #{allowBeep}


    AND a.allow_add_friend = #{allowAddFriend}


    AND a.global_recv_msg_opt = #{globalRecvMsgOpt}


    AND a.register_type = #{registerType}
